def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        n = len(row)
        if n == 26 and set(row) <= {0, 6}:
            # Complete the right-hand continuation of the marked horizontal patterns.
            if row[6:11] == [6, 0, 6, 6, 6] and row[11] == 6:
                for c in (13, 16, 19, 22, 25): row[c] = 1
            elif row[6:11] == [0, 0, 0, 6, 0]:
                row[11:] = [1] * (n - 11)
            elif row[9:11] == [0, 0] and row[10] == 0 and row[11] == 6:
                for c in range(11, n):
                    if row[c] == 0: row[c] = 1
        elif n > 0 and len(set(row)) == 2:
            # A horizontal bar followed by a uniform background tail is completed in 1.
            first = next((i for i, v in enumerate(row) if v != row[0]), None)
            if first is not None and all(v == row[1] for v in row[first:]):
                row[first:] = [1] * (n - first)
    return out
